```python
def valid_brackets(s: str) -> bool:
    # Stack to keep track of opening brackets
    stack = []
    # Mapping of opening brackets to their corresponding closing brackets
    brackets = {'(': ')', '[': ']', '{': '}'}
    # Mapping of closing brackets to their corresponding opening brackets
    reverse_brackets = {')': '(', ']': '[', '}': '{'}

    for char in s:
        # Ignore characters that are not brackets
        if char not in brackets and char not in reverse_brackets:
            continue
        # Check if the character is an opening bracket and push it onto the stack
        if char in brackets:
            stack.append(char)
        # Check if the character is a closing bracket and if it matches the latest opening bracket
        elif char in reverse_brackets:
            if not stack or stack.pop() != reverse_brackets[char]:
                return False

    # Check if all opening brackets have been matched
    return not stack
```

