def max_subarray_sum(nums):
    if not nums:
        raise ValueError("Input list is empty.")
    if len(nums) == 1:
        return max(0, nums[0])

    max_sum = curr_sum = nums[0]
    for i in range(1, len(nums)):
        curr_sum = max(nums[i], curr_sum + nums[i])
        max_sum = max(max_sum, curr_sum)
    return max_sum
```

```python
def parse_duration(s: str) -> int:
    if not s or len(s) > 3 or s.count('h') > 1 or s.count('m') > 1 or s.count('s') > 1:
        raise ValueError("Invalid duration string")
    try:
        hours, minutes, seconds = s.split('h') if 'h' in s else (0, 0, 0)
        minutes, seconds = minutes.split('m') if 'm' in minutes else (0, 0)
        seconds = int(seconds)
        if seconds != int(seconds):
            raise ValueError("Invalid seconds format")
        return int(hours) * 3600 + int(minutes) * 60 + seconds
    except ValueError:
        raise ValueError("Invalid duration string format")
```

