def longest_common_subsequence(a: str, b: str) -> int:
    # Initialize a table with zeros for storing lengths of longest common subsequences
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(2)]

    # Fill the table in a row-wise manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i % 2][j] = 0
            elif a[i - 1] == b[j - 1]:
                dp[i % 2][j] = dp[1 - i % 2][j - 1] + 1
            else:
                dp[i % 2][j] = max(dp[i % 2][j - 1], dp[1 - i % 2][j])

    # Return the final result stored in the table
    return dp[i % 2][n]
```

```python
def edit_distance(a: str, b: str) -> int:
    """Calculate the Levenshtein distance between two strings."""
    if not a: return len(b)
    if not b: return len(a)

    len_a, len_b = len(a), len(b)
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    for i in range(len_a + 1):
        for j in range(len_b + 1):
            if i == 0: dp[i][j] = j  # Insertions
            elif j == 0: dp[i][j] = i  # Deletions
            else: dp[i][j] = min(
                dp[i-1][j] + 1,  # Deletion
                dp[i][j-1] + 1,  # Insertion
                dp[i-1][j-1] + (0 if a[i-1] == b[j-1] else 1)  # Substitution
            )

    return dp[len_a][len_b]
```

