import heapq

def shortest_paths(graph: dict[str, list[tuple[str, int]]], source: str) -> dict[str, int]:
    # Initialize distances and priority queue
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heapq.heqopop(priority_queue)[0]
        # If a shorter path is found, update the distance
        if current_distance > distances[current_node]:
            distances[current_node] = current_distance
            for neighbor, weight in graph[current_node]:
                new_distance = current_distance + weight
                if new_distance < distances[neighbor]:
                    distances[neighbor] = new_distance
                    heapq.heappush(priority_queue, (new_distance, neighbor))

    return {node: dist for node, dist in distances.items() if dist < float('inf')}
```

