def count_n_queens(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    elif n == 0:
        return 1
    else:
        def solve(col, row):
            if col == n:
                return 1
            else:
                total = 0
                for i in range(n):
                    if i != col and i != row and i != col + row - col and i != col + row + col:
                        total += solve(col + 1, i)
                return total

        return solve(0, -1)
```

```python
def valid_brackets(s: str) -> bool:
    """
    Checks if the brackets in the string s are correctly matched and nested.

    Args:
        s (str): The input string containing brackets.

    Returns:
        bool: True if every opening bracket has a corresponding closing bracket and they are properly nested; False otherwise.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or stack.pop() != bracket_map[char]:
                return False

    return not stack  # If stack is empty, all brackets were properly matched
```

```python
def count_n_queens(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1

    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve(board, col):
        if col >= n:
            return 1

        total_ways = 0
        for i in range(n):
            if is_safe(board, i, col):
                # Place queen
                board[i][col] = 1
                # Move on to the next column
                total_ways += solve(board, col + 1)
                # Remove queen (backtrack)
                board[i][col] = 0

        return total_ways

    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve(board, 0)
```
